use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm::{self, Reply};
use crate::aap::caps::types::Intent;

struct Node;

const SYSTEM: &str = "You are a customer-support assistant. Answer the customer's \
question using only the provided knowledge. If you need more information, request \
the `lookup` tool with a search query.";

/// Upper bound on tool-orchestration rounds, so a model that keeps asking for
/// lookups cannot loop forever.
const MAX_ROUNDS: usize = 4;

/// Upper bound on the byte length of a model-chosen lookup query.
const MAX_QUERY_BYTES: usize = 512;

fn intent_label(intent: Intent) -> &'static str {
    match intent {
        Intent::BillingQuestion => "billing-question",
        Intent::TechnicalSupport => "technical-support",
        Intent::AccountChange => "account-change",
        Intent::GeneralInquiry => "general-inquiry",
        Intent::Unknown => "unknown",
    }
}

fn truncate_to(s: &str, max_bytes: usize) -> &str {
    if s.len() <= max_bytes {
        return s;
    }
    let mut end = max_bytes;
    while !s.is_char_boundary(end) {
        end -= 1;
    }
    &s[..end]
}

fn build_prompt(ctx: &ConversationContext) -> String {
    let mut prompt = String::new();
    prompt.push_str("Intent: ");
    prompt.push_str(intent_label(ctx.intent));
    prompt.push_str("\n\nCustomer question:\n");
    prompt.push_str(&ctx.question);
    prompt.push_str("\n\nKnowledge:\n");
    for entry in &ctx.knowledge {
        prompt.push_str("- ");
        prompt.push_str(entry);
        prompt.push('\n');
    }
    prompt
}

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        let mut prompt = build_prompt(&ctx);

        for _ in 0..MAX_ROUNDS {
            match tool_llm::generate(SYSTEM, &prompt) {
                Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                Reply::Call(request) => {
                    if request.tool != "lookup" {
                        return ResponseResult::Error(LlmError {
                            message: format!("tool not permitted: {}", request.tool),
                        });
                    }
                    let query = truncate_to(&request.query, MAX_QUERY_BYTES);
                    let hits = kb_read::lookup(query);

                    prompt.push_str("\n\nLookup results for \"");
                    prompt.push_str(query);
                    prompt.push_str("\":\n");
                    for hit in &hits {
                        prompt.push_str("- ");
                        prompt.push_str(hit);
                        prompt.push('\n');
                    }
                }
            }
        }

        ResponseResult::Error(LlmError {
            message: "tool-call budget exhausted without a text answer".to_string(),
        })
    }
}

export!(Node);
```

